contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt to set owner, record outcome, and assert general property
    function run(address newOwner) public payable {
        // precondition: none (true)
        require(true);

        // read owner before call
        address before = c.owner();

        // only the current owner (this contract) can succeed; since c was deployed by this test deployer,
        // but the checker deploys c with msg.sender = this test contract, so this contract is the initial owner.
        // Call setOwner and capture whether it reverted and its return value if not.
        bool reverted;
        bool returnedFalse = false;
        try c.setOwner(newOwner) returns (bool retval) {
            reverted = false;
            returnedFalse = (retval == false);
        } catch {
            reverted = true;
        }

        // read owner after call
        address after = c.owner();

        // General rule: if the call did not revert then it must have returned true and the contract's owner must now equal newOwner.
        // If it reverted then owner must remain unchanged.
        assert((!reverted && !returnedFalse && after == newOwner) || (reverted && after == before));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller (this contract) is the owner of c because
    // the checker deploys a fresh c and then deploys this test with c passed in;
    // per environment msg.sender for c's constructor was the deployer of c (not this)
    // but the problem statement guarantees the checker deploys a fresh c and runs run
    // with this contract as msg.sender when calling c, so we must first ensure this
    // contract is the owner by calling setOwner from the real owner. To do that we
    // accept an address currentOwner and use it only to gate the setup via try/catch.
    function run(address assumedOwner) public payable {
        require(assumedOwner != address(0));

        // Read owner before any state change
        address before = c.owner();

        // If this contract is not the owner yet, attempt to setOwner to this contract
        // by asking the assumedOwner (externally) to have previously been owner.
        // We cannot cause an external account to call, so we detect whether the test
        // contract is already owner; if not, we cannot proceed to call setOwner as owner
        // so we skip calling and assert a property that still holds: if we are not owner,
        // then calling setOwner with same owner by this contract must revert (non-owner cannot set)
        bool reverted;
        if (before == address(this)) {
            // perform the no-op setOwner call: setOwner(address(this))
            bool ok;
            try c.setOwner(address(this)) returns (bool success) {
                reverted = false;
                ok = success;
            } catch {
                reverted = true;
                ok = false;
            }
            // after calling, read owner and require the call did not change it
            address after = c.owner();
            // General rule: when the current owner calls setOwner with the same address
            // it should not revert, should return true, and owner remains identical
            assert(!reverted && ok && after == before);
        } else {
            // If this contract is not the owner, then calling setOwner to 'before' (the current owner)
            // must revert and must not change owner. We attempt the call and capture revert.
            bool ok;
            try c.setOwner(before) returns (bool success) {
                reverted = false;
                ok = success;
            } catch {
                reverted = true;
                ok = false;
            }
            address after = c.owner();
            // General rule: a non-owner cannot successfully call setOwner even to set the owner
            // to the same current owner; hence it must revert and owner stays the same.
            assert(reverted && !ok && after == before);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address assumedOwner) public payable {
        require(assumedOwner != address(0));

        // read owner before any state change
        address before = c.owner();

        bool reverted;
        bool ok;

        if (before == address(this)) {
            // this contract is the owner: calling setOwner with same address should succeed
            try c.setOwner(address(this)) returns (bool success) {
                reverted = false;
                ok = success;
            } catch {
                reverted = true;
                ok = false;
            }

            // read owner after call
            address ownerAfter = c.owner();

            // General rule for owner no-op: call does not revert, returns true, and owner unchanged
            assert(!reverted && ok && ownerAfter == before);
        } else {
            // this contract is not the owner: calling setOwner to the current owner must revert
            try c.setOwner(before) returns (bool success) {
                reverted = false;
                ok = success;
            } catch {
                reverted = true;
                ok = false;
            }

            address ownerAfter = c.owner();

            // General rule for non-owner attempt: call reverts (thus ok==false) and owner unchanged
            assert(reverted && !ok && ownerAfter == before);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address /*unused*/ ) public payable {
        // read owner before any state change
        address before = c.owner();

        // We must perform both possible calls as top-level statements so the checker can analyze each path.
        // Call A: attempt to set owner to this contract's address
        bool revertedA;
        bool okA;
        // perform call A
        try c.setOwner(address(this)) returns (bool successA) {
            revertedA = false;
            okA = successA;
        } catch {
            revertedA = true;
            okA = false;
        }

        // Call B: attempt to set owner to the recorded 'before' address
        bool revertedB;
        bool okB;
        // perform call B
        try c.setOwner(before) returns (bool successB) {
            revertedB = false;
            okB = successB;
        } catch {
            revertedB = true;
            okB = false;
        }

        // read owner after calls
        address after = c.owner();

        // Single assert expressing the general rule:
        // If this contract was the owner before, then the call setting owner to this contract must not revert, must return true, and owner remains unchanged.
        // If this contract was not the owner before, then the call setting owner to 'before' must revert and owner remains unchanged.
        assert(
            // owner unchanged in all cases
            after == before
            && (
                // case: this contract was owner -> callA succeeded
                (before == address(this) && !revertedA && okA)
                ||
                // case: this contract was not owner -> callB reverted
                (before != address(this) && revertedB && !okB)
            )
        );
    }

    receive() external payable {}
}

