    // single public test function: caller (this contract) is the current owner because
    // the checker deploys a fresh C with owner = msg.sender (the deployer), and deployer
    // is the test deployer; thus this contract is the owner at start of run.
    function run(address newOwner) public payable {
        require(true);

        // Read owner before call
        address before = c.owner();

        // Make the modifying call: since this contract deployed C, it should be the owner
        bool reverted;
        bool returned;
        try c.setOwner(newOwner) returns (bool ok) {
            reverted = false;
            returned = ok;
        } catch {
            reverted = true;
            returned = false;
        }

        address after = c.owner();

        // General rule: when the current owner (this contract) calls setOwner, it must not revert,
        // must return true, and owner() must equal the provided newOwner.
        // We express that by asserting: if before == address(this) then not reverted && returned && after == newOwner.
        assert((before != address(this)) || (!reverted && returned && after == newOwner));
    }

    receive() external payable {}
